127	## `RecordsPage`'s responsibilities (presentation, not part of the bloc — this is where `SessionBloc` is imported)
128	
129	```dart
130	class _RecordsPageState extends State<RecordsPage> {
131	  late final StreamSubscription<void> _reauthSubscription;
132	  final _scrollController = ScrollController();   // never recreated — preserves scroll position (FR-003/FR-007)
133	
134	  @override
135	  void initState() {
136	    super.initState();
137	    _reauthSubscription = context.read<RecordsBloc>().reauthRequired.listen((_) {
138	      context.read<SessionBloc>().add(const AuthExpiredDetected());   // the only cross-bloc touch point — lives in a widget, not a BLoC
139	    });
140	    _scrollController.addListener(_maybeRequestNextPage);
141	  }
142	
143	  void _maybeRequestNextPage() {
144	    if (_scrollController.position.pixels >= _scrollController.position.maxScrollExtent - 200) {
145	      context.read<RecordsBloc>().add(const NextPageRequested());
146	    }
147	  }
148	
149	  Future<void> _openEmptyStateCreate(BuildContext context) async {
150	    await openInsertionModal(context);   // research.md R10 — shared with Home/Chat's "+"
151	    if (mounted) context.read<RecordsBloc>().add(const RecordsLocalCacheRefreshed());
152	  }
153	}
154	```
