1	import 'package:cerne/core/network/api_client.dart';
2	import 'package:cerne/core/network/failure.dart';
3	import 'package:cerne/features/entries/domain/entities/entry.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	/// The only class that calls `ApiClient.call('entries-create', ...)` and
7	/// parses the full [Entry] response shape (data-model.md,
8	/// contracts/entries-repository.md). Never sends
9	/// `occurredAt`/`mediaDurationSeconds`/`chatMessageId` in the request body.
10	class EntriesRemoteDataSource {
11	  const EntriesRemoteDataSource(this._apiClient);
12	
13	  final ApiClient _apiClient;
14	
15	  Future<Either<Failure, Entry>> create({
16	    required String content,
17	    required EntrySource source,
18	  }) async {
19	    final result = await _apiClient.call(
20	      'entries-create',
21	      method: 'POST',
22	      body: {'content': content, 'source': source.name},
23	    );
24	
25	    return result.flatMap(_parseEntry);
26	  }
27	
28	  Either<Failure, Entry> _parseEntry(Map<String, dynamic> data) {
29	    try {
30	      final entry = Entry(
31	        id: data['id'] as String,
32	        content: data['content'] as String,
33	        source: EntrySource.values.byName(data['source'] as String),
34	        chatMessageId: data['chatMessageId'] as String?,
35	        occurredAt: DateTime.parse(data['occurredAt'] as String),
36	        tags: (data['tags'] as List<dynamic>)
37	            .map(
38	              (t) => EntryTag(
39	                id: (t as Map<String, dynamic>)['id'] as String,
40	                name: t['name'] as String,
41	              ),
42	            )
43	            .toList(),
44	        piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
45	        piiSpans: (data['piiSpans'] as List<dynamic>)
46	            .map(
47	              (s) => PiiSpan(
48	                start: (s as Map<String, dynamic>)['start'] as int,
49	                end: s['end'] as int,
50	                type: s['type'] as String,
51	              ),
52	            )
53	            .toList(),
